import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";import{b as i,y as a}from"./chunks/assets.DMkeNHu3.js";var o=JSON.parse(`{"title":"Theme Design","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/11-theme-design.md","filePath":"02-consumer/11-theme-design.md"}`),s={name:`02-consumer/11-theme-design.md`};function c(n,o,s,c,l,u){return r(),t(`div`,null,[...o[0]||=[e(`<h1 id="theme-design" tabindex="-1">Theme Design <a class="header-anchor" href="#theme-design" aria-label="Permalink to “Theme Design”">​</a></h1><p>In this section, you can easily customize all parts of the website and enjoy the changes.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>It is strongly recommended that you apply Theme changes to a local, non-production version.</p></div><p>Despite the recommendation above, these editing features are also available in the production version. You can use them.</p><h2 id="selecting-an-area" tabindex="-1">Selecting an Area <a class="header-anchor" href="#selecting-an-area" aria-label="Permalink to “Selecting an Area”">​</a></h2><p><img src="`+i+`" alt="theme-list.webp" width="1920" height="1512"></p><p>This section contains all the available sections so you can customize different Areas as needed. The list of Areas is displayed here.</p><h3 id="special-sections" tabindex="-1">Special Sections: <a class="header-anchor" href="#special-sections" aria-label="Permalink to “Special Sections:”">​</a></h3><ul><li>Default header: Specifies the site&#39;s default header, not a complete Area</li><li>Default footer: Specifies the site&#39;s default footer, not a complete Area</li><li>Preloader: Displays a preloader on all pages</li><li>Floats: Provides floating sections on all pages.</li><li>Build assets: Automatically runs the theme build commands. It is recommended that you do not use this in the production version.</li><li>The Rounded button at the end, with a code icon, displays the Segment list and Theme sections in one Area.</li><li>The other sections correspond to different parts of the site.</li></ul><h2 id="editing-an-area" tabindex="-1">Editing an Area <a class="header-anchor" href="#editing-an-area" aria-label="Permalink to “Editing an Area”">​</a></h2><p><img src="`+a+`" alt="theme-edit.webp" width="1920" height="3609"></p><p>Details for editing an Area:</p><ul><li>Use default: Specifies whether to use the default header and footer</li><li>Below are all the sections, or Theme Parts, with the following options: <ul><li>Delete</li><li>Edit, meaning replace it with another Segment</li><li>Reorder</li></ul></li><li>There is also an add button at the end</li></ul><h3 id="editing-or-adding-a-part" tabindex="-1">Editing or Adding a Part <a class="header-anchor" href="#editing-or-adding-a-part" aria-label="Permalink to “Editing or Adding a Part”">​</a></h3><p>When you click Add or Edit, a list of permitted Theme Parts is displayed.</p><ol><li>You can select a part by viewing its preview.</li><li>You can use search or filters.</li><li>After selecting a part, click the Save button at the bottom.</li></ol><h3 id="what-happens-after-saving" tabindex="-1">What Happens After Saving <a class="header-anchor" href="#what-happens-after-saving" aria-label="Permalink to “What Happens After Saving”">​</a></h3><p>After saving, the Theme section&#39;s settings will be updated according to your requirements. You can then update the settings for the Theme sections.</p><p>After completing all edits, click the Build Assets button to apply the final changes, or run the following commands:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> # or npm</span></span></code></pre></div>`,20)]])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};